import "./index.css";
import Borders from './Borders';
import Paddings from './Paddings';
import Margins from './Margins';
import Corners from './Corners';
import Dimensions from './Dimensions';
import Positions from './Positions';
import Zindex from './Zindex';
import Float from "./Float";
import GridLayout from './GridLayout';
import Flex from './Flex';
import ReactIconsSampler from "./ReactIcons";
import BootstrapGrids from './BootstrapGrids';
import ScreenSizeLabel from './ScreenSizeLabel';
import BootstrapLists from './BootstrapLists';
import BootstrapForms from './BootstrapForms';
import BootstrapNavigations from "./BootstrapNavigations";

export default function Lab2() {
  return (
    <div className="container">
      {/* Inline Style Attribute Section */}
      <h2>Lab 2 - Cascading Style Sheets</h2>
      <h3>Styling with the STYLE attribute</h3>
      <p>
        Style attribute allows configuring look and feel right on the element.
        Although it's very convenient, it is considered bad practice and you should avoid using the style attribute.
      </p>
      <Borders />
      <Paddings />
      <Margins />
      <Corners />
      <Dimensions />
      <Positions />
      <Zindex />
      <Float />
      <GridLayout />
      <Flex />
      <ReactIconsSampler />
      <BootstrapGrids />
      <ScreenSizeLabel />
      <BootstrapLists />
      <BootstrapForms />
      <BootstrapNavigations />

      {/* ID Selectors */}
      <div id="wd-css-id-selectors">
        <h3>ID selectors</h3>
        <p id="wd-id-selector-1">
          Instead of changing the look and feel of all the elements of the same name, e.g., P, we can refer to a specific element by its ID.
        </p>
        <p id="wd-id-selector-2">
          Here's another paragraph using a different ID and a different look and feel.
        </p>
      </div>

      {/* Class Selectors */}
      <div id="wd-css-class-selectors">
        <h3>Class selectors</h3>
        <p className="wd-class-selector">
          Instead of using IDs to refer to elements, you can use an element's CLASS attribute.
        </p>
        <h4 className="wd-class-selector">
          This heading has the same style as the paragraph above.
        </h4>
      </div>

      {/* Document Structure Selectors */}
      <div id="wd-css-document-structure">
        <div className="wd-selector-1">
          <h3>Document structure selectors</h3>
          <div className="wd-selector-2">
            Selectors can be combined to refer to elements in particular places in the document.
            <p className="wd-selector-3">
              This paragraph's red background is referenced as:
              <br />
              `.wd-selector-1 .wd-selector-3`
              <br />
              This means it’s a **descendant** of `.wd-selector-1`.
              <br />
              <span className="wd-selector-4">
                Whereas this span is a **direct child** of `.wd-selector-3`.
              </span>
              <br />
              You can combine these relationships to create specific styles based on the document structure.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
